<template>
  <main class="private-page">
    <header class="page-head"><div><p class="eyebrow">课程合作计划</p><h1>我的密价权益</h1><p>预存本金用于购课，专属价格、期限与续期进度以已确认规则为准。</p></div><el-button :loading="loading" @click="load">刷新权益</el-button></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon /><el-tabs v-model="tab">
      <el-tab-pane label="我的权益" name="rights"><section v-loading="loading" class="card-grid"><el-empty v-if="!rights.length&&!loading" description="暂无密价协议，可先查看公开套餐" /><article v-for="row in rights" :key="row.contractId" class="offer-card"><div class="offer-top"><h2>{{ row.platformName }}</h2><el-tag>{{ privateState(row.contractStatus) }}</el-tag></div><p>{{ privateMode(row.operationsMode) }} · {{ row.currentTerm?.planName||'原协议' }}</p><strong class="price">¥{{ privateMoney(row.fixedPrice) }}<small>/单</small></strong><p>专户余额 ¥{{ privateMoney(row.walletBalance) }}</p><p>购买期截止：{{ row.validUntil?privateDate(row.validUntil):'未设置结束时间' }}</p><p v-if="row.currentTerm?.rules?.renewalPolicy==='PERFORMANCE'">有效消费 ¥{{ privateMoney(row.currentTerm.settledConsumptionAmount) }}，距目标还差 ¥{{ privateMoney(row.currentTerm.remainingConsumption) }}</p><div class="actions"><el-button type="primary" :disabled="!row.currentTermId" @click="inspect(row.currentTermId)">查看权益与进度</el-button><el-button v-if="row.currentTerm?.canRequestRenewal" @click="openApply({...row.currentTerm.renewalOffer,canApply:true})">申请原约定续期</el-button><el-button @click="$router.push('/courses')">选择课程</el-button><el-button @click="$router.push('/course-wallets')">转入预存</el-button><el-button @click="openRelease(row)">申请余额转回</el-button></div></article></section></el-tab-pane>
      <el-tab-pane label="可申请套餐" name="plans"><section v-loading="loading" class="card-grid"><el-empty v-if="!plans.length&&!loading" description="暂无公开套餐，请联系运营" /><article v-for="plan in plans" :key="plan.planId" class="offer-card"><div class="offer-top"><h2>{{ plan.planName }}</h2><el-tag>{{ privateMode(plan.rules?.mode) }}</el-tag></div><p>{{ plan.description||'预存款保留在本课程专户，仅用于该商品。' }}</p><strong class="price">¥{{ privateMoney(plan.rules?.fixedPrice) }}<small>/单</small></strong><dl><dt>首次预存</dt><dd>¥{{ privateMoney(plan.rules?.initialDepositAmount) }} 本金</dd><dt>权益期限</dt><dd>{{ plan.rules?.validityDays?`${plan.rules.validityDays} 天`:'长期，不设置固定到期日' }}</dd><dt>续期条件</dt><dd>{{ renewalText(plan.rules) }}</dd></dl><el-button type="primary" :disabled="!plan.canApply" @click="openApply(plan)">申请或续约</el-button><p v-if="!plan.canApply">{{ plan.unavailableReason||'当前暂停申请' }}</p></article></section><el-pagination v-if="planTotal>20" v-model:current-page="planPage" :page-size="20" :total="planTotal" layout="prev,pager,next" @current-change="load" /></el-tab-pane>
      <el-tab-pane label="权益申请" name="applications"><el-empty v-if="!applications.length" description="暂无权益申请" /><article v-for="app in applications" :key="app.id" class="record-card"><div><strong>{{ app.planName }} · {{ appType(app.applicationType) }}</strong><el-tag>{{ privateState(app.status) }}</el-tag></div><p>{{ app.applicationReason }}</p><p v-if="app.reviewReason">审核意见：{{ app.reviewReason }}</p><small>{{ privateDate(app.submittedAt) }}</small><el-button v-if="app.status==='PENDING'" :disabled="busy" @click="cancelApplication(app)">撤销申请</el-button></article></el-tab-pane>
      <el-tab-pane label="余额转回申请" name="releases"><el-alert title="申请不冻结专户余额，也不表示已经转回。审核前仍可消费，批准时余额不足会保留待处理。" type="info" :closable="false" show-icon /><el-empty v-if="!releases.length" description="暂无余额转回申请" /><article v-for="item in releases" :key="item.id" class="record-card"><div><strong>申请转回 ¥{{ privateMoney(item.amount) }}</strong><el-tag>{{ privateState(item.status) }}</el-tag></div><p>{{ item.reason }}</p><p v-if="item.reviewReason">财务意见：{{ item.reviewReason }}</p><small>{{ privateDate(item.createdAt) }}</small><el-button v-if="item.status==='PENDING'" :disabled="busy" @click="cancelRelease(item)">撤销申请</el-button></article></el-tab-pane>
      <el-tab-pane :label="`站内通知${unread?'（'+unread+' 未读）':''}`" name="notifications"><el-empty v-if="!notifications.length" description="暂无周期通知" /><article v-for="notice in notifications" :key="notice.id" class="record-card"><div><strong>{{ notice.payload?.title }}</strong><el-tag>{{ notice.readAt?'已读':'未读' }}</el-tag></div><p>{{ notice.payload?.body }}</p><p v-if="notice.payload?.planName">{{ notice.payload.planName }} · 本期 ¥{{ privateMoney(notice.payload.price) }}/单</p><p v-if="notice.payload?.remainingConsumption!==null&&notice.payload?.remainingConsumption!==undefined">当前结算进度距目标还差 ¥{{ privateMoney(notice.payload.remainingConsumption) }}，以权益详情实时核验为准。</p><p v-if="notice.payload?.endAt">购买截止：{{ privateDate(notice.payload.endAt) }}</p><small>{{ privateDate(notice.deliveredAt) }}</small><el-button @click="openNotice(notice)">查看相关权益</el-button></article><el-pagination v-if="noticeTotal>20" v-model:current-page="noticePage" :page-size="20" :total="noticeTotal" layout="prev,pager,next" @current-change="loadNotices" /></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="detailVisible" title="课程权益详情" width="min(860px,95vw)"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false" /><div v-loading="detailLoading"><CoursePrivateTermDetails :detail="detail" @inspect="inspect" /></div></el-dialog>
    <el-dialog v-model="applyVisible" :title="appType(apply.applicationType)" width="min(560px,95vw)" :close-on-click-modal="!busy" :show-close="!busy"><div class="confirm-summary"><strong>{{ selectedPlan?.planName }}</strong><template v-if="!recoveringApply"><p>本次 {{ appType(apply.applicationType) }} · 固定价 ¥{{ privateMoney(applyPrice) }}/单</p><p>{{ renewalText(applyRules) }}</p></template><p v-else>正在核对原申请，使用当时已确认的规则；当前公开价格不会改写原请求。</p><p>预存款可用于购课；审核和资格达标后生效，旧成交不会重新计价。</p></div><el-form label-position="top"><el-form-item label="申请原因"><el-input v-model="apply.reason" aria-label="权益申请原因" type="textarea" maxlength="255" :disabled="busy||recoveringApply" /></el-form-item><el-form-item v-if="apply.applicationType==='UPGRADE'&&!legacyConversion" label="生效方式"><el-select v-model="apply.effectivePolicy" aria-label="升级生效方式" :disabled="busy||recoveringApply"><el-option label="下一期生效" value="NEXT_TERM" /><el-option v-if="relation?.currentTerm?.rules?.upgradePolicy==='REVIEW_IMMEDIATE'" label="申请独立审核即时生效" value="REVIEW_IMMEDIATE" /></el-select></el-form-item><el-checkbox v-if="apply.applicationType==='REJOIN'||legacyConversion" v-model="apply.acknowledgeLegacyChange" :disabled="busy||recoveringApply">确认重新签约或转换原权益；原余额和历史保留，规则变更须审核。</el-checkbox></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><el-alert v-if="recoveringApply" title="正在核对原提交；相同内容会使用原请求，不会重复创建。" type="info" :closable="false" /><template #footer><el-button :disabled="busy" @click="applyVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitApply">{{ recoveringApply?'核对原申请':'确认提交申请' }}</el-button></template></el-dialog>
    <el-dialog v-model="releaseVisible" title="申请专户余额转回" width="min(520px,95vw)" :close-on-click-modal="!busy" :show-close="!busy"><p>{{ selectedRight?.platformName }} · 当前专户余额 ¥{{ privateMoney(selectedRight?.walletBalance) }}</p><el-alert title="审核成功后才从本课程专户转回普通余额。申请不冻结资金，不直接提现。" type="warning" :closable="false" show-icon /><el-form label-position="top"><el-form-item label="申请转回金额"><el-input v-model="release.amount" aria-label="申请转回金额" inputmode="decimal" :disabled="busy||recoveringRelease" /></el-form-item><el-form-item label="转回原因"><el-input v-model="release.reason" aria-label="余额转回原因" maxlength="255" :disabled="busy||recoveringRelease" /></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><el-alert v-if="recoveringRelease" title="核对原申请：使用已保存的金额和原请求。" type="info" :closable="false" /><template #footer><el-button :disabled="busy" @click="releaseVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitRelease">确认申请转回</el-button></template></el-dialog>
  </main>
</template>
<script setup>
import {ref,reactive,computed,onMounted,watch,onBeforeUnmount} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import * as api from '@/api/coursePrivateOperations';
import {sessionUserInfo} from '@/utils/authSession';
import {courseMoney} from '@/utils/courseWallet';
import {privateDate,privateMoney,privateState,privateMode,createPrivateRequests} from '@/utils/coursePrivateOperations';
import CoursePrivateTermDetails from '@/components/CoursePrivateTermDetails.vue';
const tab=ref('rights'),loading=ref(false),error=ref(''),rights=ref([]),plans=ref([]),applications=ref([]),releases=ref([]),planPage=ref(1),planTotal=ref(0),busy=ref(false),formError=ref('');
const notifications=ref([]),unread=ref(0),noticePage=ref(1),noticeTotal=ref(0);
const detailVisible=ref(false),detailLoading=ref(false),detailError=ref(''),detail=ref(null);
const applyVisible=ref(false),selectedPlan=ref(null),relation=ref(null),recoveringApply=ref(false),apply=reactive({applicationType:'OPEN',effectivePolicy:'ON_ACTIVATION',acknowledgeLegacyChange:false,reason:''});
const releaseVisible=ref(false),selectedRight=ref(null),recoveringRelease=ref(false),release=reactive({amount:'',reason:''});
let sessionGeneration=0,loadRevision=0,detailRevision=0,noticeRevision=0;
const keys=createPrivateRequests({userUid:()=>sessionUserInfo.value?.uid});
const legacyConversion=computed(()=>apply.applicationType==='UPGRADE'&&relation.value?.operationsMode==='LEGACY_PERMANENT');
const applyRules=computed(()=>apply.applicationType==='RENEW'&&relation.value?.currentTerm?.rules?.renewalPricePolicy==='SAME_VERSION'?relation.value.currentTerm.rules:selectedPlan.value?.rules);
const applyPrice=computed(()=>applyRules.value?.fixedPrice);
const appType=value=>({OPEN:'申请开通',RENEW:'申请续期',UPGRADE:'申请升级',REJOIN:'申请重新签约'}[value]||'权益申请');
const renewalText=rules=>rules?.renewalPolicy==='PERFORMANCE'?`每期有效消费目标 ¥${privateMoney(rules.renewalConsumptionTarget)}，原订单观察期 ${rules.settlementGraceDays} 天。`:rules?.renewalPolicy==='NEW_DEPOSIT'?`每期净新增预存 ¥${privateMoney(rules.renewalDepositAmount)}，旧余额与退款不计。`:rules?.renewalPolicy==='MANUAL'?'续期须人工补授审核。':'未配置周期续期。';
async function load(){const generation=sessionGeneration,revision=++loadRevision;loading.value=true;error.value='';const requests=[api.getPrivateRights({page:1,pageSize:100}),api.getPrivatePlans({page:planPage.value,pageSize:20}),api.getPrivateApplications({page:1,pageSize:100}),api.getPrivateReleases({page:1,pageSize:100})];const result=await Promise.allSettled(requests);if(generation!==sessionGeneration||revision!==loadRevision)return;const destinations=[rights,plans,applications,releases];result.forEach((item,index)=>{if(item.status==='fulfilled'){destinations[index].value=item.value.data.records||[];if(index===1)planTotal.value=item.value.data.total||0;}else error.value=item.reason?.message||'部分数据加载失败，请刷新重试';});loading.value=false;await loadNotices();}
// 通知独立加载，失败时不覆盖已成功读取的资金与权益。
async function loadNotices(){const generation=sessionGeneration,revision=++noticeRevision;try{const data=(await api.getPrivateNotifications({page:noticePage.value,pageSize:20})).data;if(generation!==sessionGeneration||revision!==noticeRevision)return;notifications.value=data.records||[];unread.value=data.unread||0;noticeTotal.value=data.total||0;}catch(e){if(generation!==sessionGeneration||revision!==noticeRevision)return;error.value=e.message||'通知读取失败，请刷新重试';}}
async function openNotice(notice){const generation=sessionGeneration;try{await api.readPrivateNotification(notice.id);if(generation!==sessionGeneration)return;await loadNotices();if(generation!==sessionGeneration)return;await inspect(notice.payload.termId);}catch(e){ElMessage.error(e.message||'通知读取失败');}}
async function inspect(id){const generation=sessionGeneration,revision=++detailRevision;detailVisible.value=true;detailLoading.value=true;detailError.value='';detail.value=null;try{const data=(await api.getPrivateTerm(id)).data;if(generation!==sessionGeneration||revision!==detailRevision)return;detail.value=data;}catch(e){if(generation!==sessionGeneration||revision!==detailRevision)return;detailError.value=e.message||'权益详情读取失败';}finally{if(generation===sessionGeneration&&revision===detailRevision)detailLoading.value=false;}}
async function openApply(plan){if(busy.value)return;const generation=sessionGeneration;formError.value='';selectedPlan.value=plan;try{const result=await api.getPrivateRights({page:1,pageSize:20,platformId:plan.platformId});if(generation!==sessionGeneration)return;relation.value=result.data.records?.[0]||null;const row=relation.value;const type=!row?'OPEN':row.contractStatus==='TERMINATED'?'REJOIN':row.currentTerm?.planId===plan.planId?'RENEW':'UPGRADE';const legacy=type==='UPGRADE'&&row?.operationsMode==='LEGACY_PERMANENT';if(type==='RENEW'&&row.currentTerm?.canRequestRenewal===false)throw new Error(`当前不在续期窗口：${privateDate(row.currentTerm.renewalWindowStart)} ～ ${privateDate(row.currentTerm.renewalWindowEnd)}`);if(type==='UPGRADE'&&row.currentTerm?.canRequestUpgrade===false)throw new Error('原权益暂不能升级，可能已有下一期或尚未激活，请查看权益详情。');if(legacy&&plan.rules?.upgradePolicy!=='REVIEW_IMMEDIATE')throw new Error('此套餐尚未允许旧协议转换，请联系运营配置明确转换政策。');Object.assign(apply,{applicationType:type,effectivePolicy:type==='OPEN'||type==='REJOIN'?'ON_ACTIVATION':legacy?'REVIEW_IMMEDIATE':'NEXT_TERM',acknowledgeLegacyChange:false,reason:'确认本人课程合作规则并申请权益'});const prior=keys.peek(`apply:${plan.planId}:${type}`);recoveringApply.value=!!prior;if(prior)Object.assign(apply,prior.body);applyVisible.value=true;}catch(e){if(generation!==sessionGeneration)return;ElMessage.error(e.message||'申请条件读取失败');}}
async function submitApply(){if(busy.value)return;const generation=sessionGeneration;formError.value='';try{if(!apply.reason.trim())throw new Error('请填写申请原因');if((apply.applicationType==='REJOIN'||legacyConversion.value)&&!apply.acknowledgeLegacyChange)throw new Error('请明确确认原权益变化');const plan=selectedPlan.value,row=relation.value;const version=apply.applicationType==='RENEW'&&row?.currentTerm?.rules?.renewalPricePolicy==='SAME_VERSION'?row.currentTerm.planVersionId:plan.planVersionId;const body={planId:plan.planId,planVersionId:version,applicationType:apply.applicationType,sourceTermId:['RENEW','UPGRADE'].includes(apply.applicationType)?row?.currentTermId:null,effectivePolicy:apply.effectivePolicy,acknowledgeLegacyChange:apply.acknowledgeLegacyChange,reason:apply.reason.trim()};const scope=`apply:${plan.planId}:${apply.applicationType}`;const prior=keys.peek(scope);const saved=keys.begin(scope,prior?.body||body);busy.value=true;await api.submitPrivateApplication({...saved.body,requestKey:saved.requestKey});if(generation!==sessionGeneration)return;keys.confirmed(scope,saved.requestKey);applyVisible.value=false;tab.value='applications';await load();ElMessage.success('申请已记录，资金和资格以审核结果为准');}catch(e){if(generation!==sessionGeneration)return;formError.value=e.message||'结果暂未确认，请在申请记录核对或恢复原请求重试';try{recoveringApply.value=!!keys.peek(`apply:${selectedPlan.value.planId}:${apply.applicationType}`);}catch{} }finally{if(generation===sessionGeneration)busy.value=false;}}
function openRelease(row){if(busy.value)return;selectedRight.value=row;formError.value='';Object.assign(release,{amount:'',reason:'申请将剩余课程本金转回普通余额'});try{const prior=keys.peek(`release:${row.walletId}`);recoveringRelease.value=!!prior;if(prior)Object.assign(release,prior.body);releaseVisible.value=true;}catch(e){ElMessage.error(e.message);}}
async function submitRelease(){if(busy.value)return;const generation=sessionGeneration;formError.value='';try{const amount=courseMoney(release.amount);if(amount==='0.00'||!release.reason.trim())throw new Error('请填写正金额及转回原因');const scope=`release:${selectedRight.value.walletId}`;const body={walletId:selectedRight.value.walletId,amount,reason:release.reason.trim()};const saved=keys.begin(scope,body);busy.value=true;await api.submitPrivateRelease({...saved.body,requestKey:saved.requestKey});if(generation!==sessionGeneration)return;keys.confirmed(scope,saved.requestKey);releaseVisible.value=false;tab.value='releases';await load();ElMessage.success('已提交转回申请，当前余额未因申请改变');}catch(e){if(generation!==sessionGeneration)return;formError.value=e.message||'请核对原申请后用相同请求重试';try{recoveringRelease.value=!!keys.peek(`release:${selectedRight.value.walletId}`);}catch{} }finally{if(generation===sessionGeneration)busy.value=false;}}
async function cancelApplication(item){await cancel(item,api.cancelPrivateApplication,'撤销权益申请不会改变资金。');}
async function cancelRelease(item){await cancel(item,api.cancelPrivateRelease,'撤销待处理申请，不会产生转回流水。');}
async function cancel(item,fn,message){if(busy.value)return;const generation=sessionGeneration;try{await ElMessageBox.confirm(message,'确认撤销',{type:'warning'});if(generation!==sessionGeneration)return;busy.value=true;await fn(item.id);if(generation!==sessionGeneration)return;await load();}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'撤销失败');}finally{if(generation===sessionGeneration)busy.value=false;}}
// 身份切换立即清空私有视图，并阻止旧响应或旧申请覆盖新账户。
watch(()=>sessionUserInfo.value?.uid,()=>{sessionGeneration++;loadRevision++;detailRevision++;noticeRevision++;rights.value=[];plans.value=[];applications.value=[];releases.value=[];notifications.value=[];unread.value=0;planTotal.value=0;noticeTotal.value=0;detail.value=null;relation.value=null;selectedPlan.value=null;selectedRight.value=null;detailVisible.value=false;applyVisible.value=false;releaseVisible.value=false;busy.value=false;loading.value=false;detailLoading.value=false;error.value='';formError.value='';if(sessionUserInfo.value?.uid)load();},{flush:'sync'});
onBeforeUnmount(()=>{sessionGeneration++;loadRevision++;detailRevision++;noticeRevision++;});
onMounted(load);
</script>
<style scoped>
.private-page{width:100%;box-sizing:border-box;grid-template-columns:minmax(0,1fr);padding:22px;display:grid;gap:20px;max-width:1400px;margin:auto}.page-head{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.page-head h1{font-size:27px;margin:4px 0 10px}.page-head p{margin:0;color:var(--el-text-color-secondary)}.eyebrow{font-size:12px;letter-spacing:.12em}.card-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:18px}.offer-card,.record-card{background:var(--el-bg-color);border:1px solid var(--el-border-color-light);border-radius:14px;padding:22px}.offer-top{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.offer-top h2{font-size:18px;margin:0}.offer-card p,.record-card p{color:var(--el-text-color-secondary);line-height:1.6}.price{font-size:34px;display:block;margin:18px 0}.price small{font-size:13px;margin-left:5px;color:var(--el-text-color-secondary)}dl{display:grid;grid-template-columns:90px 1fr;gap:10px;font-size:14px}dt{color:var(--el-text-color-secondary)}dd{margin:0}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions .el-button{margin:0}.record-card{margin-bottom:12px}.record-card>div{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.record-card small{color:var(--el-text-color-secondary);margin-right:15px}.confirm-summary{padding:15px;border-radius:8px;background:var(--el-fill-color-light);margin-bottom:15px}.el-pagination{margin-top:20px;overflow:auto}.private-page>*{min-width:0}header>div{min-width:0;max-width:100%}@media(max-width:600px){.private-page{padding:12px;gap:12px}.card-grid{grid-template-columns:1fr}.offer-card{padding:18px}.page-head h1{font-size:24px}.el-tabs :deep(.el-tabs__nav-wrap){max-width:100%}}
</style>
